//! Shortening ("mangling") of the export names a module exposes to other modules.
//!
//! A module's export keys usually only exist to link modules together: the producing module emits
//! `{ someVeryLongExportName: () => … }` and every consumer reads
//! `ns["someVeryLongExportName"]`. Both sides are generated by us, so the key can be replaced by a
//! much shorter one — as long as producer and consumer agree, and as long as the name is not
//! observable from user code. Eligible members of scope-hoisted groups compute their names in a
//! shared scope, with distinct keys for each `(module, export)` binding. Other members keep their
//! own source-module namespaces.
//!
//! [`export_info`] is the single source of truth for the namespace target and export names. Both
//! the producer ([`super::export::EsmExports::code_generation`]) and the consumer
//! ([`super::base::ReferencedAsset`]) ask it about the module that produces the binding, so they
//! cannot disagree. Export metadata uses the same per-source-module decision, whether the module
//! shares a flat table, mangles independently, or keeps its original namespace and names. Callers
//! looking up an output key do not need to branch on eligibility: [`ExportInfo::export_name`] falls
//! back to the original name when there is no mapping.
//!
//! **Every** piece of code generation that materializes an export access **as a string** must use
//! both [`ExportInfo::namespace`] and [`ExportInfo::export_name`] from that result. This includes
//! generated source text (`__turbopack_require__(id)["default"](…)` and friends) and AST built by
//! hand. A hard-coded `["someExport"]` silently misses once the target's exports are mangled, and
//! using the original module ID can address the wrong namespace when exports share a flat table.
//! `ReferencedAssetIdent` handles this automatically for generated ESM imports. For a re-export,
//! resolve to the module that actually produces the binding before calling [`export_info`].

mod table;

use anyhow::Result;
use bincode::{Decode, Encode};
use turbo_frozenmap::FrozenMap;
use turbo_rcstr::RcStr;
use turbo_tasks::{ResolvedVc, Vc};
use turbopack_core::{
    chunk::{ChunkingContext, MergeableModuleExposure},
    module_graph::{binding_usage_info::ModuleExportUsageInfo, merged_modules::MergedModuleGroup},
};

use self::table::shorten_to_unique_names;
use crate::chunk::{EcmascriptChunkPlaceable, EcmascriptExports};

/// The namespace and names used to register and read a source module's exports.
#[turbo_tasks::value]
pub struct ExportInfo {
    namespace: ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>,
    /// Original export name -> the key actually used in the output.
    ///
    /// `None` means the module is ineligible for mangling and keeps every original name (see
    /// [`export_info`] for the conditions). `Some` means eligible, not necessarily renamed:
    /// standalone maps contain only names that actually changed, omitting names that kept
    /// themselves (for example, because they were already short enough). Flat tables explicitly
    /// cover every export and can map a name to itself, since their computation keys include
    /// source-module identity. A missing key always means "use the original name".
    ///
    /// Callers that only need the output key use [`Self::export_name`] without checking
    /// eligibility. The `canMangle` reporting in [`crate::references::exports_info`] instead
    /// needs to distinguish "ineligible" from "eligible but unchanged", which is what
    /// [`Self::can_mangle_names`] exposes.
    names: Option<FrozenMap<RcStr, RcStr>>,
    flat: bool,
}

impl ExportInfo {
    fn unmangled(module: ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>) -> Self {
        Self {
            namespace: module,
            names: None,
            flat: false,
        }
    }

    pub fn namespace(&self) -> ResolvedVc<Box<dyn EcmascriptChunkPlaceable>> {
        self.namespace
    }

    /// The output key to use for the given export.
    pub fn export_name<'a>(&'a self, name: &'a RcStr) -> &'a RcStr {
        self.names
            .as_ref()
            .and_then(|names| names.get(name))
            .unwrap_or(name)
    }

    /// Whether the module's export names are eligible for mangling, even if none actually changed.
    /// An individual export must also be used to be a candidate; unused exports are not emitted.
    pub fn can_mangle_names(&self) -> bool {
        self.names.is_some()
    }

    pub fn is_flat(&self) -> bool {
        self.flat
    }
}

/// The scope for computing export names. Group keys include the original member
/// index, so two source modules exporting the same name still get distinct output properties.
#[turbo_tasks::task_input]
#[derive(Copy, Clone, Debug, Eq, PartialEq, Hash, Encode, Decode)]
pub(crate) enum ExportNamesScope {
    Single(ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>),
    Group(ResolvedVc<MergedModuleGroup>),
}

/// Computed export names and the source-module identity used for their namespace.
#[turbo_tasks::value]
pub(crate) struct ComputedExportNames {
    /// The source-module identity used for the namespace. In mixed groups this may differ
    /// from the merged factory's original entry, which needs its own namespace.
    pub entry: ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>,
    pub names: rustc_hash::FxHashMap<
        ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>,
        FrozenMap<RcStr, RcStr>,
    >,
}

#[turbo_tasks::value(transparent)]
pub(crate) struct OptionComputedExportNames(pub Option<ResolvedVc<ComputedExportNames>>);

#[turbo_tasks::function]
pub(crate) async fn compute_export_names(
    scope: ExportNamesScope,
    chunking_context: Vc<Box<dyn ChunkingContext>>,
) -> Result<Vc<OptionComputedExportNames>> {
    let flat = matches!(scope, ExportNamesScope::Group(_));
    let (preferred_entry, modules) = match scope {
        ExportNamesScope::Single(module) => (ResolvedVc::upcast(module), vec![(0, module)]),
        ExportNamesScope::Group(group) => {
            let group = group.await?;
            // Only externally read members contribute to the shared table. Internal namespaces
            // keep their source identity; unexposed members only use local bindings.
            let modules = group
                .modules
                .await?
                .iter()
                .enumerate()
                .filter(|(_, (_, exposure))| *exposure == MergeableModuleExposure::External)
                .filter_map(|(index, (module, _))| {
                    ResolvedVc::try_sidecast::<Box<dyn EcmascriptChunkPlaceable>>(*module)
                        .map(|module| (index, module))
                })
                .collect();
            (group.entry, modules)
        }
    };
    let mut exports_to_name = Vec::new();
    let mut eligible_modules = Vec::new();
    for (index, module) in modules {
        // Non-static export shapes need their existing runtime representation without
        // excluding eligible peers from the shared table.
        let EcmascriptExports::EsmExports(exports) = *module.get_exports().await? else {
            continue;
        };
        // Disabled for the module that owns these exports, independently of minification:
        // mangling and minification are separate concerns, and callers may want either alone.
        // An observable namespace needs original names and a distinct object, not the
        // shared table. Its peers can still flatten independently.
        if !exports.await?.mangle_export_names {
            continue;
        }
        let usage = chunking_context
            .module_export_usage(*ResolvedVc::upcast(module))
            .await?;
        // Renaming (and sharing a namespace when flat) is only safe when all reads are known
        // named accesses lowered by codegen, not user-observable namespace reads.
        if usage.namespace_object_may_escape {
            continue;
        }
        let usage_info = usage.export_usage.await?;
        let ModuleExportUsageInfo::Exports(used) = &*usage_info else {
            continue;
        };
        if !flat && used.is_empty() {
            continue;
        }
        let expanded = exports.expand_exports(*usage.export_usage).await?;
        // Runtime re-exports such as `export * from "./some-dynamic-cjs"` discover names
        // dynamically and access properties by their original names. We cannot compute
        // collision-free keys or rewrite every access to the shared table ahead of time.
        if !expanded.dynamic_exports.is_empty() || (!flat && expanded.exports.is_empty()) {
            continue;
        }
        // Preserve even a flat member with no used exports, since imports must still target
        // the shared factory and agree with its empty registration. Standalone modules with
        // no used exports, or whose used set resolves to no actual exports, have nothing to
        // rename and keep their unmangled representation.
        eligible_modules.push(module);
        for name in expanded.exports.keys() {
            let key = if flat {
                RcStr::from(format!("{index}:{name}"))
            } else {
                name.clone()
            };
            exports_to_name.push((module, name.clone(), key));
        }
    }
    let Some(entry) = eligible_modules
        .iter()
        .find(|module| ResolvedVc::upcast(**module) == preferred_entry)
        .or_else(|| eligible_modules.first())
        .copied()
    else {
        return Ok(Vc::cell(None));
    };
    // Every emitted export participates, including `default` and `__esModule`.
    //
    // Neither is a runtime contract *as an export name*. The runtime paths that look `default` up
    // by name — CommonJS interop in `esmNamespaceObject` and the proxy traps in
    // `ensureDynamicExports` — only apply to CommonJS targets and modules with dynamic
    // re-exports, which keep their original names via the checks above. `__esModule` signals
    // CommonJS interop to ESM, so an ESM module exporting it is just using an ordinary export
    // name. However, `__esModule` cannot be assigned as an output key to another export because
    // the runtime defines that property itself; see `RESERVED_KEYS` in `table`.
    let computed_names = shorten_to_unique_names(exports_to_name.iter().map(|(_, _, key)| key));
    let mut names = eligible_modules
        .into_iter()
        .map(|module| (module, Vec::new()))
        .collect::<rustc_hash::FxHashMap<_, _>>();
    for (module, name, key) in exports_to_name {
        // Standalone maps omit unchanged keys. Flat maps explicitly cover every export,
        // since producers and metadata also use them to distinguish shared bindings.
        if let Some(output_name) = computed_names.get(&key) {
            names
                .entry(module)
                .or_default()
                .push((name, output_name.clone()));
        } else if flat {
            names.entry(module).or_default().push((name, key));
        }
    }
    Ok(Vc::cell(Some(
        ComputedExportNames {
            entry,
            names: names
                .into_iter()
                .map(|(module, names)| (module, FrozenMap::from_iter(names)))
                .collect(),
        }
        .resolved_cell(),
    )))
}

/// Resolves the namespace target, output keys and registration mode of `module` together.
/// For a re-export, pass the source module that actually produces the binding.
/// Scope-hoisting membership comes from the analysis already stored on the chunking context,
/// read through a keyed lookup for this module rather than depending on the entire groups map.
///
/// Both the producing and the consuming side call this for the same `module`, which is what
/// guarantees they agree. The mapping covers the module's *used* exports: unused exports are not
/// emitted at all, so giving them names would only make the remaining names longer.
///
/// A module keeps its original names when any of these hold:
///
/// 1. mangling is disabled for the module that owns these exports,
/// 2. its export usage is [`ModuleExportUsageInfo::All`] — a namespace import, a computed property
///    access, an unresolvable `export *`, or a module referenced from outside the module graph
///    (entries, which are seeded with `All`). This is what a plain `import * as ns` reaches in
///    practice, whether or not the namespace object escapes: the reads are not enumerated, so the
///    usage widens to `All`. Note that widening propagates, so splitting such a module into a
///    facade and a locals module does not rescue the locals module,
/// 3. it is read through a namespace value whose used names *are* known — in practice a dynamic
///    `import()` with an enumerated export list (`import(/* webpackExports: [...] */ "…")`). We
///    know which names are used, but not that every read of them was lowered to a direct named
///    access, so an original name may still be read by user code,
/// 4. its exports are not statically known ECMAScript exports, or contain dynamic re-exports.
///
/// None of these depend on the individual export, so "is `e` a candidate for mangling" is exactly
/// "does [`ExportInfo::can_mangle_names`] return true, and is `e` used" — the per-name step
/// (hashing into a short identifier and resolving collisions) never itself excludes a name.
#[turbo_tasks::function]
pub async fn export_info(
    module: ResolvedVc<Box<dyn EcmascriptChunkPlaceable>>,
    chunking_context: Vc<Box<dyn ChunkingContext>>,
) -> Result<Vc<ExportInfo>> {
    let group = if let Some(groups) = *chunking_context.merged_modules().await?
        && let Some(group) = groups.get(&ResolvedVc::upcast(module)).await?.as_deref()
    {
        Some(ExportNamesScope::Group(*group))
    } else {
        None
    };
    for scope in group
        .into_iter()
        .chain(std::iter::once(ExportNamesScope::Single(module)))
    {
        if let Some(computed_names) = *compute_export_names(scope, chunking_context).await?
            && let computed_names = computed_names.await?
            && let Some(names) = computed_names.names.get(&module)
        {
            return Ok(ExportInfo {
                namespace: computed_names.entry,
                names: Some(names.clone()),
                flat: matches!(scope, ExportNamesScope::Group(_)),
            }
            .cell());
        }
    }
    Ok(ExportInfo::unmangled(module).cell())
}
